    this.server.registerTool('list_shared_pages', { description: '共有ページ一覧を取得します.' }, async () => { const listed = await env.SHARE_BUCKET.list({ prefix: 'pages/', delimiter: '/' }); const pages = []; for (const prefix of listed.delimitedPrefixes || []) { const pageId = prefix.split('/')[1]; const meta = await isLive(env, pageId); if (meta && meta !== 'expired') pages.push({ ...meta, url: `${origin}/p/${pageId}`, downloadUrl: `${origin}/p/${pageId}/download` }); } return { content: [{ type: 'text', text: JSON.stringify(pages.sort((a, b) => b.expiresAt - a.expiresAt), null, 2) }] }; });
